function watch<T extends object>(target: T, onChange: <K extends keyof T>(key: K, oldV: T[K], newV: T[K]) => void): T {
    return new Proxy(target, {
        set(obj, prop, value) {
            const key = prop as keyof T
            onChange(key, obj[key], value)
            obj[key] = value
            return true
        },
    })
}

