function groupBy<T, K extends keyof T>(items: T[], key: K): Map<T[K], T[]> {
    const groups = new Map<T[K], T[]>()
    for (const item of items) {
        const list = groups.get(item[key]) ?? []
        list.push(item)
        groups.set(item[key], list)
    }
    return groups
}

