type Box<T> = { get: () => T; set: (value: T) => void }
type Boxes<T> = { [K in keyof T]: Box<T[K]> }

function toBoxes<T extends object>(initial: T): Boxes<T> {
    const result = {} as Boxes<T>
    for (const key of Object.keys(initial) as (keyof T)[]) {
        let current = initial[key]
        result[key] = { get: () => current, set: value => { current = value } }
    }
    return result
}

