type PropEventSource<T> = {
    on<K extends string & keyof T>(eventName: `${K}Changed`, callback: (newValue: T[K]) => void): void
}

function makeWatched<T extends object>(obj: T): T & PropEventSource<T> {
    const callbacks: Record<string, ((value: unknown) => void)[]> = {}
    const on = (eventName: string, callback: (value: unknown) => void) => {
        callbacks[eventName] = [...(callbacks[eventName] ?? []), callback]
    }
    const proxy = new Proxy(obj, {
        get: (target, key) => (key === "on" ? on : Reflect.get(target, key)),
        set(target, key, value) {
            Reflect.set(target, key, value)
            callbacks[`${String(key)}Changed`]?.forEach(callback => callback(value))
            return true
        },
    })
    return proxy as T & PropEventSource<T>
}

