function partial<A extends unknown[], B extends unknown[], R>(
    fn: (...args: [...A, ...B]) => R,
    ...head: A
): (...tail: B) => R {
    return (...tail) => fn(...head, ...tail)
}

const greet = (greeting: string, name: string, mark: string) => `${greeting}, ${name}${mark}`
