type Expr =
    | { kind: "num"; value: number }
    | { kind: "add"; left: Expr; right: Expr }
    | { kind: "mul"; left: Expr; right: Expr }
    | { kind: "neg"; operand: Expr }

function evaluate(e: Expr): number {
    switch (e.kind) {
        case "num": return e.value
        case "add": return evaluate(e.left) + evaluate(e.right)
        case "mul": return evaluate(e.left) * evaluate(e.right)
        case "neg": return -evaluate(e.operand)
    }
}

function toText(e: Expr): string {
    switch (e.kind) {
        case "num": return String(e.value)
        case "add": return `(${toText(e.left)} + ${toText(e.right)})`
        case "mul": return `(${toText(e.left)} * ${toText(e.right)})`
        case "neg": return `-${toText(e.operand)}`
    }
}

// 2 + 3 * (-4)
const expr: Expr = {
    kind: "add",
    left: { kind: "num", value: 2 },
    right: { kind: "mul", left: { kind: "num", value: 3 }, right: { kind: "neg", operand: { kind: "num", value: 4 } } },
}

