type DeepPartial<T> = T extends object ? { [K in keyof T]?: DeepPartial<T[K]> } : T

type Settings = {
    server: { host: string; port: number; tls: { enabled: boolean; cert: string } }
    debug: boolean
}

const defaults: Settings = {
    server: { host: "localhost", port: 3000, tls: { enabled: false, cert: "" } },
    debug: false,
}

function merge<T extends object>(base: T, patch: DeepPartial<T>): T {
    const result = { ...base } as Record<string, unknown>
    for (const [key, value] of Object.entries(patch)) {
        const current = result[key]
        const bothObjects = typeof value === "object" && value !== null && typeof current === "object" && current !== null
        result[key] = bothObjects ? merge(current, value) : value
    }
    return result as T
}

const custom = merge(defaults, { server: { port: 8080, tls: { enabled: true } } })
