type Events = {
    login: [user: string]
    purchase: [item: string, price: number]
    logout: []
}

class Emitter {
    private handlers: Record<string, ((...args: any[]) => void)[]> = {}

    on<E extends keyof Events>(event: E, handler: (...args: Events[E]) => void): this {
        const list = this.handlers[event] ?? []
        list.push(handler)
        this.handlers[event] = list
        return this
    }

    emit<E extends keyof Events>(event: E, ...args: Events[E]): void {
        for (const handler of this.handlers[event] ?? []) handler(...args)
    }
}

const bus = new Emitter()
bus.on("login", user => console.log("kirdi:", user))
    .on("purchase", (item, price) => console.log(`sotib oldi: ${item} — ${price} so'm`))
    .on("logout", () => console.log("chiqdi"))

bus.emit("login", "Aziz")
