type Zip<A extends unknown[], B extends unknown[]> =
    A extends [infer HA, ...infer RA]
        ? B extends [infer HB, ...infer RB] ? [[HA, HB], ...Zip<RA, RB>] : []
        : []

type Pairs = Zip<[1, 2, 3], ["a", "b", "c"]>   // [[1, "a"], [2, "b"], [3, "c"]]

function zip<A extends unknown[], B extends unknown[]>(a: [...A], b: [...B]): Zip<A, B> {
    const size = Math.min(a.length, b.length)
    return Array.from({ length: size }, (_, i) => [a[i], b[i]]) as Zip<A, B>
}

const pairs = zip([1, 2, 3], ["a", "b", "c"])
