type Get<T, P extends readonly PropertyKey[]> =
    P extends readonly [infer K, ...infer R extends PropertyKey[]]
        ? K extends keyof T ? Get<T[K], R> : undefined
        : T

function get<T, P extends PropertyKey[]>(obj: T, ...path: P): Get<T, P> {
    return path.reduce<any>((value, key) => value?.[key], obj)
}

