type Curried<A extends unknown[], R> =
    A extends [infer H, ...infer T] ? (arg: H) => Curried<T, R> : R

function curry<A extends unknown[], R>(fn: (...args: A) => R): Curried<A, R> {
    const step = (collected: unknown[]) => (arg: unknown) => {
        const next = [...collected, arg]
        return next.length >= fn.length ? fn(...(next as A)) : step(next)
    }
    return step([]) as Curried<A, R>
}

const volume = (width: number, height: number, depth: number) => width * height * depth
const curried = curry(volume)                  // (arg: number) => (arg: number) => (arg: number) => number

console.log(curried(2)(3)(4))
const withWidth2 = curried(2)
console.log(withWidth2(5)(10))

