interface Duck extends Swimmer, Walker {}      // tip: Duck'da swim va walk bor

function applyMixins(target: { prototype: object }, sources: { prototype: object }[]): void {
    for (const source of sources) {
        for (const key of Object.getOwnPropertyNames(source.prototype)) {
            if (key === "constructor") continue
            Object.defineProperty(target.prototype, key, Object.getOwnPropertyDescriptor(source.prototype, key)!)
        }
    }
}

applyMixins(Duck, [Swimmer, Walker])           // metodlarni haqiqatan ko'chiramiz

const duck = new Duck()
console.log(duck.name, duck.swim(), duck.walk())

