declare global {
    namespace Express {
        interface Request { url: string }
    }
}

// 2) Siz o'z faylingizda xuddi shu interface'ga qo'shasiz
declare global {
    namespace Express {
        interface Request { user?: { id: number; role: string } }
    }
}

function handle(req: Express.Request): string {
    return req.user ? `${req.url}: ${req.user.role}` : `${req.url}: mehmon`
}

